"""Plain-language interface copy and display labels. No analysis or generation logic."""
import re
import pandas as pd
from .study import NAMES,OUTCOMES,label,selected_fields

def plain(text):
    """Display form of source wording: sentences in place of semicolons and dashes."""
    text=str(text).replace(' — ',': ').replace('—',': ').replace('This is baseline age, not MIDUS 3 age.','This is baseline age.')
    return re.sub(r';\s+(\w)',lambda m:'. '+m.group(1).upper(),text)

