def metric_name(code):return METRICS[code][0]

def variable_guide(study):
    rows=[]
    for f in selected_fields(study):
        spec=study['variables'][study['outcomes'].get(f,f)]
        allowed=' · '.join(f'{k} = {v}' for k,v in spec['categories'].items()) if spec['kind']=='category' else f'{spec["minimum"]} to {spec["maximum"]}'
        rows.append({'CSV column name':f,'Variable':label(study,f),'Allowed values / codes':allowed,
                     'Meaning of the score':plain(spec.get('scoring','')),'Missing values':'Leave blank for missing input values. Pilot data need both life-satisfaction outcomes.'})
    return pd.DataFrame(rows)

def readable_records(frame,study):
    display=frame.copy()
    for f in selected_fields(study):
        if f not in display:continue
        spec=study['variables'][study['outcomes'].get(f,f)]
        if spec['kind']=='category':display[f]=display[f].map(lambda v:None if pd.isna(v) else spec['categories'].get(int(v),v))
    return display.rename(columns={**{f:label(study,f) for f in selected_fields(study)},'participant_id':'Participant ID'})

def readable_results(frame):
    d=frame.copy()
    for f in ['method','first','second']:
        if f in d:d[f]=d[f].map(lambda m:__import__('spa.recommendations',fromlist=['public_label']).public_label(m))
    if 'wave' in d:d['wave']=d.wave.map({0:'Psychological score distributions',2:'MIDUS 2: baseline life satisfaction',3:'MIDUS 3: later life satisfaction'})
    if 'metric' in d:d['metric']=d.metric.map(metric_name)
    if 'significant' in d:d['significant']=d.significant.map({True:'Yes',False:'No'})
    return d.rename(columns={'method':'Method','first':'First method','second':'Second method','wave':'Assessment / comparison',
      'domain':'Evaluation type','metric':'Measure','n':'Datasets included','mean':'Average across datasets','lower':'Lower 95% confidence limit',
      'upper':'Upper 95% confidence limit','difference':'First minus second','p_display':'Adjusted p-value','significant':'Statistically significant?',
      'p_adjusted':'Adjusted p-value','welch_df':'Welch degrees of freedom','se':'Standard error of the difference','n_first':'Scored datasets for first method','n_second':'Scored datasets for second method','family_size':'Number of adjusted comparisons','distribution_runs':'Datasets with score results','sd':'Average score SD','smd':'Standardised mean error',
      'sd_ratio':'SD ratio','sd_error':'SD-ratio error','wasserstein':'Normalised Wasserstein distance',
      'midus2_runs':'Datasets with baseline correlations','midus2_mean_r':'Average baseline correlation','midus2_mae':'Baseline correlation error',
      'midus3_runs':'Datasets with later correlations','midus3_mean_r':'Average later correlation','midus3_mae':'Later correlation error',
      'code':'CSV variable code','variable':'Psychological variable'})
